<?php $isLogout = $action === '/logout'; ?>
<section class="panel confirmation-panel"><span class="empty-icon <?= $isLogout ? '' : 'danger-icon' ?>"><?= icon($isLogout ? 'logout' : 'trash',32) ?></span><p class="eyebrow"><?= $isLogout ? 'A PAUSE BETWEEN CHAPTERS' : 'A MOMENT TO DOUBLE CHECK' ?></p><h1><?= e($heading) ?></h1><p><?= e($message) ?></p><?php if (!$isLogout): ?><div class="confirmation-note"><?= icon('info',18) ?><span>This action cannot be undone. Take a moment to make sure.</span></div><?php endif; ?><div class="form-actions centered"><a class="btn btn-secondary" href="<?= e(url($cancel)) ?>"><?= $isLogout ? 'Keep learning' : 'Keep it' ?></a><form method="post" action="<?= e(url($action)) ?>"><?= csrf_field() ?><input type="hidden" name="confirm" value="yes"><button class="btn <?= $isLogout ? 'btn-primary' : 'btn-danger' ?>" type="submit"><?= icon($isLogout ? 'logout' : 'trash',17) ?> <?= $isLogout ? 'Log out' : 'Confirm deletion' ?></button></form></div></section>
